    lfs_size_t lookahead_blocks = lfs->cfg->lookahead_size * 8;
    lfs_block_t start_block = lfs->lookahead_block;
    if (start_block == LFS_BLOCK_NULL) {
        start_block = 0;
    }

    uint8_t *buffer = (uint8_t *)lfs->cfg->lookahead_buffer;
    lfs_size_t buffer_size = lfs->cfg->lookahead_size;

    for (lfs_size_t i = 0; i < buffer_size; i++) {
        lfs_block_t block = (start_block + i * 8) % lfs->block_count;
        uint8_t map = 0;
        for (int j = 0; j < 8; j++) {
            lfs_block_t b = (block + j) % lfs->block_count;
            if (lfs_block_is_free(lfs, b)) {
                map |= (1 << j);
            }
        }
        buffer[i] = map;
    }
    lfs->lookahead_block = start_block;
}

uint8_t *buffer = (uint8_t *)lfs->cfg->lookahead_buffer;
lfs_size_t buffer_size = lfs->cfg->lookahead_size;

for (lfs_size_t i = 0; i < buffer_size; i++) {
    if (buffer[i]) {
        for (int j = 0; j < 8; j++) {
            if (buffer[i] & (1 << j)) {
                lfs_block_t block = (lfs->lookahead_block + i * 8 + j) % lfs->block_count;
                if (lfs_block_is_free(lfs, block)) {
                    *block = block;
                    buffer[i] &= ~(1 << j);
                    return LFS_ERR_OK;
                }
            }
        }
    }
}

return LFS_ERR_NOSPC;

